import XCTest

final class PhoenixUITests: XCTestCase {
    override func setUpWithError() throws {
        continueAfterFailure = true
    }

    func dump(_ app: XCUIApplication, _ tag: String) {
        let desc = app.debugDescription
        print("===HIERARCHY \(tag)===\n\(desc)\n===END \(tag)===")
        let url = FileManager.default.temporaryDirectory.appendingPathComponent("hierarchy_\(tag).txt")
        try? desc.write(to: url, atomically: true, encoding: .utf8)
    }

    func testSendStatusUpdate() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.launch()

        dump(app, "roomlist")

        let cell = app.cells.containing(.staticText, identifier: "Project Phoenix").firstMatch
        if cell.waitForExistence(timeout: 20) {
            cell.tap()
        } else {
            app.staticTexts["Project Phoenix"].firstMatch.tap()
        }

        sleep(2)
        dump(app, "room")

        let composer = app.textViews.firstMatch
        XCTAssertTrue(composer.waitForExistence(timeout: 20), "composer not found")
        composer.tap()
        composer.typeText("status update")

        dump(app, "typed")

        var sent = false
        for id in ["Send", "send", "Send message", "sendButton", "Send message button"] {
            let b = app.buttons[id].firstMatch
            if b.exists {
                b.tap()
                sent = true
                break
            }
        }
        if !sent {
            let b = app.buttons.matching(NSPredicate(format: "label CONTAINS[c] 'send' OR identifier CONTAINS[c] 'send'")).firstMatch
            if b.exists {
                b.tap()
                sent = true
            }
        }

        sleep(1)
        dump(app, "aftersend")
        XCTAssertTrue(sent, "send button not found/tapped")
    }
}

import XCTest

final class PhoenixUITests: XCTestCase {
    override func setUpWithError() throws {
        continueAfterFailure = true
    }

    func dump(_ app: XCUIApplication, _ tag: String) {
        let desc = app.debugDescription
        print("===HIERARCHY \(tag)===\n\(desc)\n===END \(tag)===")
    }

    func testSendStatusUpdate() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.launch()
        sleep(1)

        let phoenixCell = app.cells.containing(.staticText, identifier: "Project Phoenix").firstMatch
        if !phoenixCell.exists {
            let allChats = app.buttons["All chats"]
            if allChats.waitForExistence(timeout: 5) {
                allChats.tap()
                sleep(1)
            }
        }
        XCTAssertTrue(phoenixCell.waitForExistence(timeout: 20), "room list cell not found")
        phoenixCell.tap()

        let gotIt = app.buttons["Got it"]
        if gotIt.waitForExistence(timeout: 5) {
            gotIt.tap()
        }

        let composer = app.textViews["GrowingTextView"]
        XCTAssertTrue(composer.waitForExistence(timeout: 20), "composer not found")
        composer.tap()
        composer.typeText("status update")

        let send = app.buttons["SendButton"]
        XCTAssertTrue(send.waitForExistence(timeout: 10), "send not found")
        let enabled = NSPredicate(format: "isEnabled == true")
        expectation(for: enabled, evaluatedWith: send, handler: nil)
        waitForExpectations(timeout: 10)
        send.tap()

        sleep(2)
        dump(app, "aftersend")
    }
}
